for(const [activity,slug,title,materials,models,matClass] of phase3) packs[slug]={title,activity,grades:'K–8',accent:'#b83280',materials,directions:['Give partners identical materials and place a barrier between them.','The Describer selects a hidden model or challenge.','Use precise shape, size, orientation, pattern, and position language to guide the Builder.','Compare, find the first mismatch, revise one direction, and switch roles.'],accommodations:'Begin with fewer pieces; provide the vocabulary strip and allow repeated directions. Items use text, shape, pattern, or icon rather than color alone.',reference:'<h2>Teacher reference</h2><div class="key">Compare item count, relative size, orientation, overlap, sequence, and position. Included models are original and noncommercial. Accept alternatives when supported by the prompt.</div><p class="note">Avoid judging identity, culture, emotion, diet, ability, or historical experience from appearance alone; adapt examples to local curriculum and student needs.</p>',pieces:phase3Pieces,challenges:models.split('|'),workmats:[`${title} student mat|near • middle • far • left/right • notes|${matClass}`]};

const phase2 = {
  'cup-coordinate-build': { title:'Cup Coordinate Build', activity:5, grades:'K–8', accent:'#b45309', materials:'Coordinate mats, orientation keys, cup tokens, and challenge cards.', directions:['Align both mats with START nearest the students.','The Describer places cups by column, row, and stack level.','The Builder recreates the arrangement behind a barrier.','Compare from the shared START edge and revise ambiguous coordinates.'], accommodations:'Begin on a 3 × 3 mat with one level. Tokens differ by number and pattern, not color alone.', reference:'<h2>Orientation key</h2><div class="key">Name column first, then row (for example, 2-B). Keep START nearest each student and north pointing away. For stacks, name levels from bottom to top.</div>', pieces:['cup 1|1|dots','cup 2|2|stripe','cup 3|3|grid','cup 4|4|cross','cup 5|5|zigzag','cup 6|6|bands','level 1|L1|plain','level 2|L2|plain','level 3|L3|plain','north|N ↑|arrow'], challenges:['Diagonal|Place cups at 1-A, 2-B, and 3-C.|one cup per cell','Corners|Fill the four corner cells.|leave center empty','Center stack|Stack three cups at 2-B.|name bottom to top','L shape|Use five cups to make an L.|state every coordinate'], workmats:['Cup coordinate mat|START at bottom • columns 1–3 • rows A–C|coordinate'] },
  'pixel-art-dictation': { title:'Pixel-Art Dictation', activity:24, grades:'K–8', accent:'#b83280', materials:'Blank grids in three sizes, patterned pixels, samples, and coordinate key.', directions:['Choose identical grid sizes.','The Describer chooses or creates a hidden pixel design.','Name each coordinate and pattern for the Builder.','Compare row by row and locate the first mismatch.'], accommodations:'Start with 5 × 5 and one pattern. Say column then row. Patterns remain distinct in grayscale.', reference:'<h2>Coordinate and sample key</h2><div class="key">Columns run left to right; rows run bottom to top. Say column first. For a 5 × 5 X, fill cells where column and row match or where their positions total 6.</div>', pieces:['solid pixel|■|plain','dot pixel|■|dots','stripe pixel|■|stripe','grid pixel|■|grid','cross pixel|■|cross','blank / erase|□|plain'], challenges:['5 × 5 X|Fill both diagonals.','5 × 5 frame|Fill the outside edge.','Symmetry|Mirror a design across the vertical center.','Original|Use 12 or fewer pixels and write its key.'], workmats:['5 × 5 pixel grid|columns 1–5 • rows A–E|pixel p5','8 × 8 pixel grid|columns 1–8 • rows A–H|pixel p8','10 × 10 pixel grid|columns 1–10 • rows A–J|pixel p10'] },
  'community-map-builder': { title:'Community Map Builder', activity:40, grades:'3–8', accent:'#b83280', materials:'Street maps, building and feature cards, compass keys, and challenges.', directions:['Orient both maps north-up.','The Describer places community features.','Describe blocks, intersections, adjacency, and direction.','Compare and discuss access, safety, and land use.'], accommodations:'Begin with six landmarks. Preteach intersection, block, across from, and adjacent.', reference:'<h2>Map reference</h2><div class="key">North is at the top. Avenues are numbered west to east and streets lettered south to north. Say whether a feature occupies a block or intersection. Samples are not universal community plans.</div>', pieces:['school|SCH|grid','library|LIB|stripe','fire station|FIRE|cross','clinic|MED|dots','park|PARK|waves','grocery|FOOD|bands','homes|HOME|plain','bus stop|BUS|zigzag','crosswalk|X-WALK|stripe','bike route|BIKE|dots','stream|WATER|waves','bridge|BRIDGE|grid'], challenges:['Walkable center|Library beside park; school across from both.|add crosswalk','Emergency access|Give the fire station two routes to homes.','Transit plan|Put stops near school, clinic, and grocery.','Green route|Connect homes and park by bike route.'], workmats:['Community street map|north at top • avenues 1–4 • streets A–D|streetmap'] },
  'route-on-a-map': { title:'Route on a Map', activity:51, grades:'K–8', accent:'#3f2a78', materials:'Paired maps, landmarks, route arrows, direction cards, and examples.', directions:['Give partners identical north-up maps.','The Describer places landmarks and chooses start and finish.','Communicate turns, blocks, and landmarks.','Check that every traced step stays on a path.'], accommodations:'Begin with forward, left, and right. Mark the starting facing direction.', reference:'<h2>Route key</h2><div class="key">State start and facing direction. A turn changes orientation; a cardinal direction does not depend on facing. Count one block from one intersection to the next.</div>', pieces:['start|START|grid','finish|FINISH|cross','school|SCH|stripe','park|PARK|waves','library|LIB|dots','bridge|BRIDGE|bands','left|↰|plain','right|↱|plain','straight|↑|arrow','route|━━|plain','closed|X|zigzag','north|N ↑|arrow'], challenges:['Two turns|Use exactly two turns.','Detour|Avoid the closed-road token.','Cardinal route|Use only N, S, E, and W.','Reverse|Describe the return trip.'], workmats:['Route map|north at top • connected roads • start/finish zones|streetmap'] },
  'treasure-map-directions': { title:'Treasure-Map Directions', activity:52, grades:'K–8', accent:'#3f2a78', materials:'Grid maps, obstacles, landmarks, destinations, and compass keys.', directions:['Orient both maps north-up and match obstacles.','The Describer secretly selects a destination.','Give coordinate or cardinal-direction moves.','Reveal and verify every move and final square.'], accommodations:'Use a 5 × 5 area and one-step moves. Move a traveler token after each repeated instruction.', reference:'<h2>Direction key</h2><div class="key">Moves cross one grid edge unless stated otherwise. North increases the row; east increases the column. No diagonal moves unless allowed. Obstacles cannot be entered.</div>', pieces:['traveler|YOU|grid','treasure|X|cross','tree|TREE|stripe','rock|ROCK|dots','pond|POND|waves','cliff|CLIFF|bands','bridge|BRIDGE|grid','north 1|N 1|arrow','south 1|S 1|arrow','east 1|E 1|arrow','west 1|W 1|arrow','destination|?|zigzag'], challenges:['Three landmarks|Pass three landmarks and avoid obstacles.','Shortest path|Reach treasure in fewest moves.','Coordinates|Give only destination and obstacle coordinates.','Return trip|Reverse a completed route.'], workmats:['Treasure grid map|north at top • columns 1–6 • rows A–F|treasuremap'] },
  'coordinate-plane-journey': { title:'Coordinate-Plane Journey', activity:53, grades:'5–8', accent:'#3f2a78', materials:'First- and four-quadrant mats, point/path tokens, challenges, and keys.', directions:['Choose the same plane and identify the origin.','The Describer states ordered pairs in sequence.','The Builder plots and connects the points.','Compare coordinates before the finished path.'], accommodations:'Start in quadrant I. Use x first, then y and trace from the origin.', reference:'<h2>Coordinate key</h2><div class="key">Ordered pairs are (x, y): move horizontally for x, then vertically for y. An axis point has one coordinate equal to zero. Sample rectangle: (−4,−2), (4,−2), (4,2), (−4,2).</div>', pieces:['point A|A|dots','point B|B|stripe','point C|C|grid','point D|D|cross','point E|E|zigzag','origin|O|plain','path|━▶|arrow','stop|STOP|bands'], challenges:['Triangle|(1,1) → (5,1) → (3,4) → start.','Rectangle|(−4,−2) → (4,−2) → (4,2) → (−4,2).','Axis points|(0,4), (−3,0), (0,−4), (3,0).','Original|Create six valid ordered pairs.'], workmats:['First-quadrant plane|origin bottom left • x then y • 0–10|coordinate first','Four-quadrant plane|origin centered • axes −5 to 5|coordinate four'] },
  'school-navigation-challenge': { title:'School Navigation Challenge', activity:54, grades:'K–8', accent:'#3f2a78', materials:'Neutral school maps, room cards, route challenges, and accessibility features.', directions:['Place the entrance identically on both maps.','The Describer arranges rooms and chooses a route.','The Builder places rooms and traces the route.','Compare and identify accessible-route considerations.'], accommodations:'Use one hallway and four rooms first. Pair icons with text and trace while repeating.', reference:'<h2>School-map note</h2><div class="key">This neutral practice map is not an emergency plan. Stay in corridors and use doors. Accessible routes avoid stairs. Real emergencies always follow posted school plans and staff directions.</div>', pieces:['entrance|ENTRY|grid','classroom|CLASS|plain','library|LIB|stripe','office|OFFICE|dots','cafeteria|CAFE|bands','gym|GYM|cross','restroom|RR|zigzag','stairs|STAIRS|stripe','elevator|ELEV|grid','exit|EXIT|cross','you are here|YOU|dots','closed hall|CLOSED|zigzag'], challenges:['New student|Visit classroom, office, and cafeteria.','Accessible|Reach library without stairs.','Detour|Reach gym around a closed hall.','Exit practice|Identify the nearest shown exit.'], workmats:['Neutral school map|entrance • corridors • room zones • exits|schoolmap'] },
  'cardinal-direction-builder': { title:'Cardinal-Direction Builder', activity:55, grades:'K–8', accent:'#3f2a78', materials:'Compass mats, landmarks, direction tokens, and challenges.', directions:['Align both mats north-up.','The Describer places a center and landmarks.','State direction and distance for each landmark.','Compare from the common center.'], accommodations:'Start with N, E, S, W at one distance. Add intermediate directions later.', reference:'<h2>Compass key</h2><div class="key">Clockwise: N, NE, E, SE, S, SW, W, NW. Opposites: N/S, E/W, NE/SW, NW/SE. Rings count outward from center.</div>', pieces:['center|CENTER|grid','tree|TREE|stripe','house|HOUSE|dots','pond|POND|waves','hill|HILL|bands','school|SCHOOL|cross','north|N|arrow','northeast|NE|plain','east|E|arrow','southeast|SE|plain','south|S|arrow','southwest|SW|plain','west|W|arrow','northwest|NW|plain'], challenges:['Cardinals|One landmark N, E, S, and W.','Intermediates|One at NE, SE, SW, and NW.','Opposites|Make four opposite pairs.','Mystery|Use six landmarks and two rings.'], workmats:['Compass placement mat|eight directions • three distance rings|compass'] },
  'landform-map-match': { title:'Landform Map Match', activity:56, grades:'3–8', accent:'#3f2a78', materials:'Blank maps, landform symbols, challenges, and a reference guide.', directions:['Orient both maps north-up.','The Describer places land and water features.','Use relative and cardinal directions.','Check that connected features make geographic sense.'], accommodations:'Begin with mountain, river, lake, plain, and island. Use the definition strip.', reference:'<h2>Landform key</h2><div class="key"><b>Mountain:</b> high, steep land. <b>Valley:</b> low area between higher land. <b>Plain:</b> broad, relatively flat land. <b>Plateau:</b> elevated flat area. <b>Peninsula:</b> water on three sides. <b>Island:</b> water on all sides. Rivers flow downhill.</div>', pieces:['mountain|▲|cross','hill|∩|stripe','valley|V|plain','plain|PLAIN|dots','plateau|▱|grid','river|≈|waves','lake|◯|waves','island|◉|dots','peninsula|⊂|bands','coast|COAST|zigzag','forest|♣|stripe','compass|N ↑|arrow'], challenges:['River valley|Mountains north; river through valley to lake.','Coast|Place peninsula, island, and coastal plain.','High/low|Plateau west of plain with hills between.','Original|Use eight plausible features.'], workmats:['Landform map|north at top • land/water edge • six zones|landform'] },
  'grid-robot-programmer': { title:'Grid Robot Programmer', activity:57, grades:'3–8', accent:'#2563a8', materials:'Grid mats, robot/obstacle tokens, command cards, program strips, and answer traces.', directions:['Match obstacles, robot coordinate, and orientation.','The Describer selects a target and builds a program.','The Builder executes one card at a time.','Compare the final coordinate and debug the first mismatch.'], accommodations:'Start with forward and quarter turns. Keep a visible arrow on the robot.', reference:'<h2>Command key</h2><div class="key"><b>FWD 1:</b> one square in facing direction. <b>LEFT/RIGHT:</b> rotate 90° without moving. <b>REPEAT n:</b> repeat bracketed cards only. Never enter an obstacle or leave the grid.</div>', pieces:['robot north|BOT ↑|grid','target|TARGET|cross','obstacle|BLOCK|zigzag','forward 1|FWD 1|arrow','turn left|LEFT 90°|plain','turn right|RIGHT 90°|plain','repeat 2|REPEAT 2|stripe','repeat 3|REPEAT 3|dots','start block|START [|bands','end block|] END|bands','debug|FIX|cross','stop|STOP|plain'], challenges:['Straight|1-A north to 1-E.','One turn|2-B north to 5-D; avoid obstacle.','Repeat|Use a repeat to make a square.','Debug|Insert and fix one wrong command.'], workmats:['Robot grid|north at top • columns 1–6 • rows A–F|robotgrid','Program strip|commands left to right • bracket repeats|program'] },
  'array-builder': { title:'Array Builder', activity:73, grades:'K–8', accent:'#3f2a78', materials:'Grid mats, printable counters, challenge and equation cards, and keys.', directions:['Give partners matching grids and counters.','The Describer states rows, items per row, and orientation.','The Builder creates the array.','Write equivalent addition and multiplication expressions.'], accommodations:'Begin at 5 × 5. Consistently say number of rows and number in each row.', reference:'<h2>Array key</h2><div class="key">Three rows of four shows 4 + 4 + 4 = 12 and 3 × 4 = 12. Rotating gives four rows of three; the total remains 12. Printed counters substitute for classroom counters.</div>', pieces:['counter|●|dots','counter|●|stripe','counter|●|grid','counter|●|cross','row|ROW|plain','column|COL|plain','multiply|×|bands','equals|=|plain'], challenges:['3 by 4|3 rows with 4 each.|12','5 by 2|5 rows with 2 each.|10','Same product|Two orientations for 18.|3×6 and 6×3','Mystery|Total 24; neither factor is 1.|multiple answers'], workmats:['Array grid|equal rows and columns • 10 × 10|array'] },
  'transformation-challenge': { title:'Transformation Challenge', activity:75, grades:'5–8', accent:'#3f2a78', materials:'Coordinate grids, vertex and transformation cards, challenges, and keys.', directions:['Choose the same grid and starting shape.','The Describer communicates a transformation rule.','The Builder moves every vertex and adds prime labels.','Compare ordered pairs and invariants.'], accommodations:'Begin with quadrant-I translations. Use movable vertices before drawing.', reference:'<h2>Transformation key</h2><div class="key">Translation: (x,y)→(x+a,y+b). Reflect y-axis: (−x,y). Reflect x-axis: (x,−y). Rotate 90° counterclockwise about origin: (−y,x). Rigid transformations preserve lengths and angles.</div>', pieces:['vertex A|A|dots','vertex B|B|stripe','vertex C|C|grid','vertex D|D|cross','translation|→|arrow','reflection|↔|bands','rotation|↺|zigzag','origin|O|plain'], challenges:['Translate|A(1,1), B(4,1), C(2,3); add (3,2).','Reflect y|Reflect that triangle across y-axis.','Rotate 90° CCW|A(1,1), B(3,1), C(2,3).','Two step|Translate, then reflect across x-axis.'], workmats:['Transformation grid|origin centered • axes −5 to 5 • use prime marks|coordinate four'] },
  'data-display-replication': { title:'Data-Display Replication', activity:76, grades:'3–8', accent:'#3f2a78', materials:'Blank graph templates, display/data cards, challenges, and answer keys.', directions:['Give partners the same blank template.','The Describer chooses a completed data display.','Explain title, labels, scale, categories, and values.','Compare structure before individual marks.'], accommodations:'Begin with a four-category bar graph and scale of one. Use the feature checklist.', reference:'<h2>Display checklist</h2><div class="key">Include an accurate title, labels, consistent scale, and values. Pictographs need a key. Line graphs show ordered change, often over time; line plots show frequency above a number line. Never imply an unmarked broken axis.</div>', pieces:['title|TITLE|grid','x label|X LABEL|stripe','y label|Y LABEL|dots','scale 1|0,1,2…|plain','scale 2|0,2,4…|plain','scale 5|0,5,10…|plain','bar|█|cross','point|●|dots','segment|━━|plain','picture|★|stripe','key|1 ★ = __|bands','value|VALUE|grid'], challenges:['Bar graph|Books: A=4, B=7, C=5, D=8.|scale 1','Line plot|1, 2, 2, 3, 3, 3, 4.|stack X marks','Pictograph|Plants: A=2, B=4, C=3.|one symbol each','Line graph|8am=60, 10am=66, noon=72, 2pm=74.|temperature °F'], workmats:['Bar graph|title • categories • values • scale|bargraph','Line plot|title • number line • stacked marks|lineplot','Pictograph|title • categories • symbols • key|pictograph','Line graph|title • axes • points • segments|linegraph'] }
};
Object.assign(packs, phase2);

const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const pattern = p => `<span class="symbol ${esc(p)}">`;
const piece = (x) => { const [label,symbol,pat] = x.split('|'); return `<div class="piece">${pattern(pat)}${esc(symbol)}</span><b>${esc(label)}</b></div>`; };
const page = (title, body, cls='') => `<section class="page ${cls}"><header><span>Say It, Make It · Activity ${current.activity}</span><b>${esc(title)}</b></header>${body}<footer>${esc(current.title)} · Print at 100% · CC BY 4.0</footer></section>`;
let current;

function commonPages(p) {
  const directions = `<h1>${esc(p.title)}</h1><p class="subtitle">Classroom-ready printable pack · Grades ${p.grades}</p><div class="info"><b>Pack contents</b><br>${esc(p.materials)} Two student sets are included.</div><h2>Teacher directions</h2><ol>${p.directions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h2>Before class</h2><ul><li>Print at 100% on US Letter paper. Use cardstock or laminate for reuse.</li><li>Cut on the thick solid borders. Keep Set A and Set B separate.</li><li>Give challenge/model cards only to the Describer.</li><li>Use a folder, book, or tabletop barrier so partners cannot see each other’s work.</li></ul><h2>Accessibility and accommodations</h2><p>${esc(p.accommodations)}</p>${p.safety || ''}`;
  const labels = `<h1>Storage-envelope labels</h1><div class="labels">${['Set A — Describer','Set B — Builder','Challenge / model cards','Teacher reference'].map(x=>`<div><b>${esc(p.title)}</b><br>${x}<br><small>Count pieces before storing.</small></div>`).join('')}</div><h2>Student language supports</h2><div class="wordbank"><b>Position:</b> above · below · beside · between · near · far · left · right · clockwise<br><b>Clarify:</b> “Please repeat…” · “Is ___ beside ___?” · “What should I place next?”<br><b>Compare:</b> same · different · rotate · move · replace · sequence</div>`;
  return page('Teacher directions', directions) + page('Storage and language supports', labels);
}
function setPage(p, label, pieces, title='Movable pieces') { return page(`${title} — Set ${label}`, `<h1>${esc(title)} <span class="set">Set ${label}</span></h1><p>Cut on the solid borders. This set is identical to the partner set.</p><div class="pieces">${pieces.map(piece).join('')}</div>`, 'cutpage'); }
function challengePage(p) { return page('Describer-only challenge cards', `<h1>Describer-only challenge cards</h1><p class="warning">Keep these cards hidden from the Builder.</p><div class="challenges">${p.challenges.map((x,i)=>{const parts=x.split('|');return `<article><b>Challenge ${i+1}${parts[0]&&!x.includes('|')?'':`: ${esc(parts[0])}`}</b>${parts.length>1?`<strong>${esc(parts[1])}</strong><p>${parts.slice(2).map(esc).join(' · ')}</p>`:`<p>${esc(x)}</p>`}</article>`}).join('')}</div>`); }
function workmatPage(p, mat) {
  const [title, subtitle, cls] = mat.split('|');
  return page(`${title} — Sets A and B`, `<h1>${esc(title)}</h1><p>Cut the page in half. Both partner mats are identical.</p><div class="workmats">${['A','B'].map(label=>`<div class="workmat ${esc(cls)}"><b>Set ${label} — ${esc(title)}</b><span>${esc(subtitle)}</span><div class="matgrid"><i>top / far</i><i>center</i><i>bottom / near</i></div></div>`).join('')}</div>`, 'landscape');
}
function render(p) {
  current=p; let body=commonPages(p);
  if (p.pieces) { body += setPage(p,'A',p.pieces)+setPage(p,'B',p.pieces); }
  if (p.groups) for (const [name,items] of Object.entries(p.groups)) body += setPage(p,'A',items,`${name} life cycle`)+setPage(p,'B',items,`${name} life cycle`);
  if (p.mats) body += page('Habitat mats 1–2', `<h1>Habitat mats</h1><div class="mats">${p.mats.slice(0,2).map(x=>{const [n,c]=x.split('|');return `<div class="mat ${n.toLowerCase()}"><b>${n}</b><span>${c}</span><div class="zones">near · middle · far</div></div>`}).join('')}</div>`, 'landscape') + page('Habitat mats 3–4', `<h1>Habitat mats</h1><div class="mats">${p.mats.slice(2).map(x=>{const [n,c]=x.split('|');return `<div class="mat ${n.toLowerCase()}"><b>${n}</b><span>${c}</span><div class="zones">near · middle · far</div></div>`}).join('')}</div>`, 'landscape');
  if (p.title==='Solar-System Placement') body += page('Solar-system placement mats', `<h1>Solar-system placement mat</h1><p>Print this page twice—one for each partner.</p><div class="orbits"><b>SUN</b>${[1,2,3,4,5,6,7,8].map(n=>`<i style="--n:${n}">${n}</i>`).join('')}</div><div class="direction">← nearer to Sun &nbsp; | &nbsp; farther from Sun →</div>`, 'landscape');
  if (p.atoms) { const atoms=[]; for(const a of p.atoms) for(let i=0;i<6;i++) atoms.push(a); body+=setPage(p,'A',atoms,'Atom pieces')+setPage(p,'B',atoms,'Atom pieces'); const bonds=[]; for(const b of p.bonds) for(let i=0;i<8;i++) bonds.push(b+'|plain'); body+=setPage(p,'A',bonds,'Bond pieces')+setPage(p,'B',bonds,'Bond pieces'); }
  if (p.workmats) for (const mat of p.workmats) body += workmatPage(p, mat);
  if (p.challenges) body += challengePage(p);
  body += page('Answer key / teacher reference', `<h1>${esc(p.title)} reference</h1>${p.reference}<h2>Quality check after a round</h2><ul><li>Can each student identify pieces by shape or label without relying on color?</li><li>Do both models match in pieces, order, orientation, and relative position?</li><li>Which direction was most precise? Which should be revised?</li></ul>`);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(p.title)} Complete Printable Pack</title><link rel="stylesheet" href="../pack.css"></head><body style="--accent:${p.accent}">${body}</body></html>`;
}

const manifest = [];
for (const [slug,p] of Object.entries(packs)) {
  const dir=path.join(ROOT,slug); fs.mkdirSync(dir,{recursive:true});
  const html = render(p);
  fs.writeFileSync(path.join(dir,`${slug}-complete-pack.html`),html);
  manifest.push({
    activity: p.activity, slug, title: p.title, status: 'complete',
    resourceType: 'classroom-printable-pack',
    components: ['teacher directions','two student sets','storage labels','accessibility notes','teacher reference',...(p.challenges?['Describer-only challenges']:[]),...(p.workmats?['student work mats']:[])],
    html: `printables/${slug}/${slug}-complete-pack.html`,
    pdf: `printables/${slug}/${slug}-complete-pack.pdf`,
    pngDirectory: `printables/${slug}/png-pages`,
    pageCount: (html.match(/<section class="page /g)||[]).length,
    review: p.activity >= 77 && p.activity <= 84 ? 'science/safety source review completed 2026-08-04; educator review recommended' : 'classroom review recommended'
  });
}
fs.writeFileSync(path.join(ROOT,'manifest.json'), JSON.stringify({version:1, generated:'2026-08-04', packs:manifest}, null, 2)+'\n');
console.log(`Generated ${Object.keys(packs).length} printable packs.`);
